static inline uint32_t pack4(uint8_t x,uint8_t y,uint8_t dx,uint8_t dy){return (uint32_t)x|((uint32_t)y<<8)|((uint32_t)dx<<16)|((uint32_t)dy<<24);} 
static inline void unpack4(uint32_t s,uint8_t &x,uint8_t &y,uint8_t &dx,uint8_t &dy){x=s&255;y=(s>>8)&255;dx=(s>>16)&255;dy=(s>>24)&255;}
struct FastMap{static constexpr uint32_t LG=27,SZ=1u<<LG,MASK=SZ-1;vector<uint64_t>keys;vector<uint32_t>vals;FastMap():keys(SZ,UINT64_MAX),vals(SZ,0){}static inline uint64_t hs64(uint64_t x){x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;x^=x>>31;return x;}inline uint32_t put_if_absent(uint64_t key,uint32_t val,bool &inserted){uint32_t p=(uint32_t)hs64(key)&MASK;for(;;){if(keys[p]==UINT64_MAX){keys[p]=key;vals[p]=val;inserted=true;return val;}if(keys[p]==key){inserted=false;return vals[p];}p=(p+1)&MASK;}}};
struct TC{int h;uint8_t mask;TC(int H):h(H),mask((1u<<H)-1){}pair<uint32_t,int> reduce(uint32_t s)const{uint8_t x,y,dx,dy;unpack4(s,x,y,dx,dy);int flip=!!(x&(1u<<(h-1)));if(flip){x^=mask;y^=mask;}return{pack4(x,y,dx,dy),flip};}
bool trans(uint32_t s,int c,int l,uint32_t &out,int &flip)const{uint8_t x,y,dx,dy;unpack4(s,x,y,dx,dy);int ta=l>=0?l+1:1,tb=l<0?-l+1:1,na=h+ta,nb=h+tb;int16_t L[17][17];L[h][h]=h;int cur=h;for(int k=h-1;k>=0;--k){cur-=(dx>>(h-1-k))&1;L[k][h]=cur;}cur=h;for(int k=h-1;k>=0;--k){cur-=(dy>>(h-1-k))&1;L[h][k]=cur;}auto achar=[&](int i){if(i<=h)return int((x>>(h-i))&1);int q=i-h-1;if(l>=0)return q<l?1-c:c;return c;};auto bchar=[&](int j){if(j<=h)return int((y>>(h-j))&1);int q=j-h-1;if(l<0)return q<(-l)?1-c:c;return c;};for(int i=0;i<=na;i++)for(int j=0;j<=nb;j++)if(i>h||j>h){if(i==0)L[i][j]=L[i][j-1];else if(j==0)L[i][j]=L[i-1][j];else if(achar(i)==bchar(j))L[i][j]=L[i-1][j-1]+1;else L[i][j]=max(L[i][j-1],L[i-1][j]);}int i=na,j=nb;while(i>=h&&j>=h){if(L[i][j]==L[i-1][j])--i;else if(L[i][j]==L[i][j-1])--j;else{--i;--j;}if(i==h&&j==h){uint8_t xs=x,ys=y;if(l>=0){for(int q=0;q<l;q++)xs=((xs<<1)|(1-c))&mask;xs=((xs<<1)|c)&mask;ys=((ys<<1)|c)&mask;}else{xs=((xs<<1)|c)&mask;for(int q=0;q<-l;q++)ys=((ys<<1)|(1-c))&mask;ys=((ys<<1)|c)&mask;}uint8_t ndx=0,ndy=0;for(int k=na-h+1;k<=na;k++)ndx=(ndx<<1)|(L[k][nb]-L[k-1][nb]);for(int k=nb-h+1;k<=nb;k++)ndy=(ndy<<1)|(L[na][k]-L[na][k-1]);auto r=reduce(pack4(xs,ys,ndx,ndy));out=r.first;flip=r.second;return true;}}return false;}};
static inline uint64_t key(uint32_t s,int m){return (uint64_t(s)<<15)|uint64_t(m);} 
int main(int argc,char**argv){string out=argc>1?argv[1]:"c041_product.bin";const int h=8,DEG=30;TC tc(h);uint8_t mask=(1u<<h)-1;auto sr=tc.reduce(pack4(0,0,mask,mask));uint32_t start=sr.first;FastMap idx;vector<uint64_t>states;states.reserve(10000000);states.push_back(key(start,DFASTART));bool ins;idx.put_if_absent(states[0],1,ins);FILE*fp=fopen(out.c_str(),"wb");if(!fp){perror("fopen");return 2;}size_t head=0;uint64_t rejected=0,accepted=0,canon=0;const size_t BS=50000;vector<uint64_t>oks;vector<uint32_t>row;while(head<states.size()){size_t end=min(states.size(),head+BS),n=end-head;oks.assign(n*DEG,UINT64_MAX);row.assign(n*DEG,0);uint64_t bc=0,ba=0,br=0;
#pragma omp parallel for reduction(+:bc,ba,br) schedule(static)
for(long long rr=0;rr<(long long)n;rr++){uint64_t kk=states[head+(size_t)rr];uint32_t s=(uint32_t)(kk>>15);int m=(int)(kk&32767ULL);int j=0;for(int c=0;c<2;c++)for(int l=-7;l<=7;l++,j++){uint32_t t=0;int fl=0;if(tc.trans(s,c,l,t,fl)){bc++;int z=max(-6,min(6,l));int ai=c*13+(z+6);int m2=DFATR[m][ai];if(m2>=0){if(fl)m2=DFACM[m2];oks[(size_t)rr*DEG+j]=key(t,m2);ba++;}else br++;}}}canon+=bc;accepted+=ba;rejected+=br;for(size_t k=0;k<n*DEG;k++)if(oks[k]!=UINT64_MAX){uint32_t newidx=(uint32_t)states.size()+1;uint32_t ti=idx.put_if_absent(oks[k],newidx,ins);if(ins){if(states.size()+1 >= (1u<<24)){cerr<<"overflow\n";return 7;}states.push_back(oks[k]);}row[k]=ti;}fwrite(row.data(),4,row.size(),fp);head=end;if(head%500000<BS)cerr<<"head="<<head<<" states="<<states.size()<<" acc="<<accepted<<" rej="<<rejected<<"\n";}fclose(fp);cout<<"R17 C041 gauge-equivariant reachable product with cap3 minimal length6 obstructions\nproduct_states="<<states.size()<<" canonical_transitions="<<canon<<" accepted_transitions="<<accepted<<" rejected_by_dfa="<<rejected<<"\nALL_EXACT_GRAPH_CONSTRUCTION_CHECKS_PASS\n";}
